    armL = mix(armL, ra, restW); armR = mix(armR, ra, restW);
    addL = mix(addL, -rd, restW); addR = mix(addR, rd, restW);
    elbL = mix(elbL, re, restW); elbR = mix(elbR, re, restW);
    twL = mix(twL, -rt, restW); twR = mix(twR, rt, restW);
